test('repair stores a backup and removes only a proven bilingual alias',()=>{const run=runFixture(),before=structuredClone(run);assert.equal(repairClassicDreamMoveAliases(run),true);assert.deepEqual(run.party[0].moves,['Tackle','Growl']);assert.deepEqual({...run.party[0],moves:before.party[0].moves},before.party[0]);assert.deepEqual(run.party[1],before.party[1]);assert.deepEqual(run.modifiers,before.modifiers);assert.equal(run.money,before.money);assert.deepEqual(run.dreamMoveAliasBackups,[{boxId:'one',moves:['Tackle','몸통박치기','Growl'],moveIds:['tackle','tackle','growl'],pp:{tackle:3,growl:5},roguePPUps:{tackle:2}}]);const after=structuredClone(run);assert.equal(repairClassicDreamMoveAliases(run),false);assert.deepEqual(run,after);});
test('repair defers ambiguous, active or unrelated saved states',()=>{const cases=[r=>r.screen='battle',r=>r.screen='advance',r=>r.mystery.job='battle',r=>r.mystery.stage='choose',r=>r.encounter.key='other',r=>r.combat={},r=>r.dreamMoveIdentityRule='source-v1',r=>r.dreamMoveIdentityRule='future-version',r=>r.pendingMoves=[{x:1}],r=>r.pendingGrowth=[{x:1}],r=>r.pendingCapture={},r=>r.pendingEvolution={},r=>r.challenges=[{id:11,value:1}],r=>r.challenges={invalid:true},r=>r.party[0].rogueMovesetRandomizer=1,r=>r.party[0].rogueMovesetSeed='x',r=>r.party[0].rogueSketchRule='source-v1',r=>r.party[0].rogueSketchPP=[1,2,3],r=>r.party[0].fusionSpecies=4,r=>r.party[0].moves=['Sketch','스케치'],r=>r.party[0].moves=['Tackle','Tackle'],r=>r.party[0].moves=['Hidden Power Ice','Hidden Power'],r=>r.party[0].moves=['Tackle','몸통박치기','unknown move'],r=>r.dreamMoveAliasBackups={bad:true},r=>r.party[1].boxId='one'];for(const mutate of cases){const run=runFixture();mutate(run);const before=structuredClone(run);assert.equal(repairClassicDreamMoveAliases(run),false,JSON.stringify(run));assert.deepEqual(run,before);}});
test('repair only changes active slot and retains backup through codec recovery',async()=>{const doc={coins:12,adventure:{keep:true}},state=ensureClassicState(doc,{initialStarterId:1});state.slots[0]=runFixture();state.slots[1]=runFixture();state.slots[1].id='other';const other=structuredClone(state.slots[1]),system=structuredClone(state.system);ensureClassicState(doc);assert.deepEqual(state.slots[0].party[0].moves,['Tackle','Growl']);assert.deepEqual(state.slots[1],other);assert.deepEqual(state.system,system);assert.deepEqual(doc.adventure,{keep:true});const saved=await decodeGameData(await encodeGameData(doc));assert.equal(saved.classic.slots[0].dreamMoveAliasBackups[0].moves[1],'몸통박치기');assert.deepEqual(saved.classic.slots[1],other);});
test('actual legacy Dream reward repairs confirmed alias before next saved combat',async()=>{let doc={coins:73,adventure:{safe:true}},state=ensureClassicState(doc,{initialStarterId:1}),run={id:'legacy-dream',seed:'legacy-dream',rng:1234567,wave:82,biome:1,screen:'mystery',party:[4,1,25].map((id,i)=>makeReferenceMon(id,50,{boxId:'old'+i,moves:['Splash']})),modifiers:[],formItems:{},tools:{},balls:{},encounter:{kind:'mystery',key:'weird-dream'}};state.slots[1]={id:'other',safe:true};const initial=prepareWeirdDreamEncounter(run),egg=initial.drafts[0].eggMove,known=lookup(egg);run.party[0].moves=[known.name];run.party[0].pp={[known.id]:2};run.party[0].roguePPUps={[known.id]:1};const prepared=prepareWeirdDreamEncounter(run);assert.ok(prepared.drafts[0].mon.moves.some(name=>name===egg));run.rng=prepared.rng;run.mystery={type:'weird-dream',stage:'choose',drafts:prepared.drafts,alternateTrainer:prepared.alternateTrainer};state.slots[0]=run;applyClassicAction(doc,{action:'mysterySelect',job:'transform'});applyClassicAction(doc,{action:'mysteryConfirm'});run=doc.classic.slots[0];assert.equal(run.screen,'reward');assert.equal(run.mystery.job,'transform');const original=[...run.party[0].moves];assert.equal(original.filter(name=>lookup(name).id===known.id).length,2);const view=classicGameView(doc);run=doc.classic.slots[0];assert.equal(run.party[0].moves.filter(name=>lookup(name).id===known.id).length,1);assert.deepEqual(run.dreamMoveAliasBackups[0].moves,original);assert.equal(run.party[0].roguePPUps[known.id],1);assert.equal(view.run.dreamMoveAliasBackups,undefined);doc=await decodeGameData(await encodeGameData(doc));run=doc.classic.slots[0];assert.deepEqual(doc.classic.slots[1],{id:'other',safe:true});assert.deepEqual(doc.adventure,{safe:true});assert.equal(doc.coins,73);run.combat=createClassicCombat(run,[makeReferenceMon(143,50,{boxId:'foe',moves:['Splash']})]);const slots=restoreClassicNativeBattle(run.combat,run).p1.active[0].moveSlots;assert.equal(new Set(slots.map(m=>m.id)).size,slots.length);assert.deepEqual(run.dreamMoveAliasBackups[0].moves,original);});

test('later saves only offer an explicit, backed-up alias repair',async()=>{
 const {classicMoveAliasPreview,confirmClassicMoveAliasRepair}=await import('../lib/rogue-dream-move-repair.mjs');
 const run=runFixture();run.screen='advance';run.mystery=null;run.encounter={kind:'wild'};
 const before=structuredClone(run),preview=classicMoveAliasPreview(run,'one');
 assert.deepEqual(preview,{moves:['Tackle','몸통박치기','Growl'],pairs:[{keep:'Tackle',remove:'몸통박치기'}]});assert.deepEqual(run,before);
 assert.throws(()=>confirmClassicMoveAliasRepair(run,'one',['Tackle','Growl']));assert.deepEqual(run,before);
 confirmClassicMoveAliasRepair(run,'one',preview.moves);assert.deepEqual(run.party[0].moves,['Tackle','Growl']);
 assert.deepEqual(run.party[0].pp,before.party[0].pp);assert.deepEqual(run.party[0].roguePPUps,before.party[0].roguePPUps);assert.deepEqual(run.party[1],before.party[1]);
 assert.deepEqual(run.dreamMoveAliasBackups[0],{boxId:'one',moves:before.party[0].moves,moveIds:['tackle','tackle','growl'],reason:'user-confirmed',pp:before.party[0].pp,roguePPUps:before.party[0].roguePPUps});
 const after=structuredClone(run);assert.throws(()=>confirmClassicMoveAliasRepair(run,'one',preview.moves));assert.deepEqual(run,after);
});
