test('reviewed fusion alias repair preserves donor, PP, save and unsplice',async()=>{
 const {classicMoveAliasPreview,confirmClassicMoveAliasRepair}=await import('../lib/rogue-dream-move-repair.mjs');
 const {previewClassicDnaFusion,previewClassicDnaUnsplice,validatedClassicDnaFusion}=await import('../lib/rogue-dna-fusion.mjs');
 const primary=makeReferenceMon(1,35,{boxId:'one',moves:['Tackle','몸통박치기','Growl']}),donor=makeReferenceMon(7,35,{boxId:'donor',moves:['Ember']});
 primary.pp={tackle:3,growl:5};primary.roguePPUps={tackle:2};const fused=previewClassicDnaFusion(primary,donor,{random:()=>0}).fused,run=runFixture();run.screen='advance';run.mystery=null;run.party[0]=fused;run.party[1]=makeReferenceMon(25,35,{boxId:'two',moves:['Splash']});
 const original=structuredClone(fused),other=structuredClone(run.party[1]);assert.ok(validatedClassicDnaFusion(fused));const preview=classicMoveAliasPreview(run,'one');assert.ok(preview);confirmClassicMoveAliasRepair(run,'one',preview.moves);
 assert.deepEqual(run.party[0].moves,['Tackle','Growl']);assert.deepEqual(run.party[0].rogueFusion,original.rogueFusion);assert.deepEqual(run.party[0].pp,original.pp);assert.deepEqual(run.party[0].roguePPUps,original.roguePPUps);assert.deepEqual(run.party[1],other);assert.ok(validatedClassicDnaFusion(run.party[0]));
 const saved=await decodeGameData(await encodeGameData({classic:{slots:[run]}})),restored=saved.classic.slots[0];assert.deepEqual(restored.dreamMoveAliasBackups[0].moves,original.moves);assert.deepEqual(restored.party[0].rogueFusion.donor,original.rogueFusion.donor);assert.ok(validatedClassicDnaFusion(restored.party[0]));restored.combat=createClassicCombat(restored,[makeReferenceMon(143,35,{boxId:'foe',moves:['Splash']})]);const native=restoreClassicNativeBattle(restored.combat,restored).p1.pokemon[0];assert.deepEqual(native.baseMoveSlots.map(slot=>slot.id),['tackle','growl']);assert.equal(native.baseMoveSlots[0].pp,3);const split=previewClassicDnaUnsplice(restored.party[0]);assert.deepEqual(split.primary.moves,['Tackle','Growl']);assert.equal(split.donorRestored,false);
});
