test('trainer test challenge review preserves restrictions, event state and recovered reward',async()=>{const {classicChallengeBattleEligibility}=await import('../lib/rogue-challenge-eligibility.mjs');for(const sketch of [false,true]){let doc=trainerTestChallengeFixture({sketch}),run=doc.classic.slots[0],before=structuredClone(run),view=classicGameView(doc),mon=run.party.find(p=>p.boxId==='one'),allowed=classicChallengeBattleEligibility(mon,run.challenges),preview=view.run.party.find(p=>p.boxId==='one').moveAliasRepair;assert.ok(preview);applyClassicAction(doc,{action:'repairMoveAliases',boxId:'one',confirm:true,expectedMoves:preview.moves,...(sketch?{removeIndex:2,expectedSketchPP:preview.sketchPP}:{})});assert.equal(classicChallengeBattleEligibility(run.party.find(p=>p.boxId==='one'),run.challenges),allowed);assert.deepEqual(run.challenges,before.challenges);assert.deepEqual(run.combat.challengeRestrictions,before.combat.challengeRestrictions);assert.deepEqual(run.mystery,before.mystery);assert.deepEqual(run.combat.snapshot.prng,before.combat.snapshot.prng);assert.deepEqual(classicGameView(doc).battle.requests,view.battle.requests);doc=await decodeGameData(await encodeGameData(doc));run=doc.classic.slots[0];const action=classicGameView(doc).battle.requests[0].actors[0].moves.find(m=>!m.disabled);assert.ok(action);applyClassicAction(doc,{action:'turn',command:{type:'move',move:action.id}});run=doc.classic.slots[0];assert.equal(run.screen,'battle');for(const foe of run.combat.snapshot.sides[1].pokemon){foe.hp=0;foe.fainted=true;}run.combat.snapshot.sides[1].pokemonLeft=0;run.combat.snapshot.ended=true;run.combat.snapshot.winner=run.combat.snapshot.sides[0].name;run.combat.ended=true;run.combat.winner=0;doc=await decodeGameData(await encodeGameData(doc));applyClassicAction(doc,{action:'recoverBattle'});run=doc.classic.slots[0];assert.equal(run.screen,'reward');assert.equal(run.mystery.stage,'resolved');assert.equal(doc.classic.system.eggs.filter(e=>e.productId==='epic').length,1);assert.equal(run.rewards[0].id,'relicgold');assert.deepEqual(run.challenges,before.challenges);assert.deepEqual(doc.classic.slots[1],{id:'other',safe:true});assert.deepEqual(doc.adventure,{safe:true});}});
test('trainer test challenge review excludes random moves and inconsistent restrictions',async()=>{const {classicMoveAliasPreview}=await import('../lib/rogue-dream-move-repair.mjs');for(const mutate of [r=>r.challenges.push({id:11,value:1}),r=>r.combat.challengeRestrictions.pop(),r=>delete r.challengeEligibilityRule,r=>r.npcDialogueQueue=[{id:'intro'}]]){const doc=trainerTestChallengeFixture(),run=doc.classic.slots[0];mutate(run);const before=structuredClone(run);assert.equal(classicMoveAliasPreview(run,'one'),null);assert.deepEqual(run,before);}});
import {wildEventReviewFixture} from './fixtures/wild-event-alias.mjs';
test('reviewed wild event group preserves real selection, combat and capture rewards',async()=>{for(const type of ['mysterious-chest','berries','fight-or-flight','uncommon-breed'])for(const sketch of [false,true]){let doc=wildEventReviewFixture(type,{sketch}),run=doc.classic.slots[0];assert.equal(run.screen,'battle',type);assert.equal(run.mystery.stage,'battle',type);const before=structuredClone(run),view=classicGameView(doc),preview=view.run.party.find(p=>p.boxId==='one').moveAliasRepair;assert.ok(preview,JSON.stringify({type,sketch,entry:run.pendingMysteryEntryBoost,request:run.combat.snapshot.requestState,mid:run.combat.snapshot.midTurn,activeMove:run.combat.snapshot.activeMove,activePokemon:run.combat.snapshot.activePokemon,activeTarget:run.combat.snapshot.activeTarget,depth:run.combat.snapshot.eventDepth,queue:run.combat.snapshot.queue,faint:run.combat.snapshot.faintQueue,turn:run.combat.turn,encounterId:run.encounter.team?.[0]?.boxId,teamId:run.combat.teams[1]?.[0]?.boxId}));applyClassicAction(doc,{action:'repairMoveAliases',boxId:'one',confirm:true,expectedMoves:preview.moves,...(sketch?{removeIndex:2,expectedSketchPP:preview.sketchPP}:{})});assert.deepEqual(run.mystery,before.mystery);assert.deepEqual(run.combat.snapshot.prng,before.combat.snapshot.prng);assert.deepEqual(run.combat.snapshot.field,before.combat.snapshot.field);assert.deepEqual(classicGameView(doc).battle.requests,view.battle.requests);assert.deepEqual(run.modifiers,before.modifiers);assert.deepEqual(run.balls,before.balls);doc=await decodeGameData(await encodeGameData(doc));run=doc.classic.slots[0];applyClassicAction(doc,{action:'capture',ballId:'masterball'});run=doc.classic.slots[0];assert.ok(['reward','learn','evolution','capture'].includes(run.screen),JSON.stringify({type,screen:run.screen}));assert.ok(run.mysteryState.completedWaves.includes(22),type);assert.equal(run.mystery.stage,'resolved',type);assert.deepEqual(doc.classic.slots[1],{id:'other',safe:true});assert.deepEqual(doc.adventure,{safe:true});if(type==='fight-or-flight')assert.equal(run.rewards[0]?.id,before.mystery.reward.id);}});
test('reviewed wild event group rejects mismatches and pending entry effects',async()=>{const {classicMoveAliasPreview}=await import('../lib/rogue-dream-move-repair.mjs');for(const type of ['mysterious-chest','berries','fight-or-flight','uncommon-breed'])for(const mutate of [r=>r.encounter.key='other',r=>r.mystery.stage='resolved',r=>r.encounter.noFlee=false,r=>r.combat.trainer=true,r=>r.encounter.team[0].boxId='other',r=>r.pendingMysteryEntryBoost='berries',r=>r.initialSwitchSlots=[0],r=>r.npcDialogueQueue=[{id:'intro'}]]){const run=wildEventReviewFixture(type).classic.slots[0];mutate(run);const before=structuredClone(run);assert.equal(classicMoveAliasPreview(run,'one'),null,JSON.stringify({type}));assert.deepEqual(run,before);}});
test('uncommon breed opening permits only the completed matching external attack',async()=>{const {classicMoveAliasPreview}=await import('../lib/rogue-dream-move-repair.mjs');for(const mutate of [r=>r.combat.snapshot.activeMove.isExternal=false,r=>r.combat.snapshot.activeMove.move='[Move:growl]',r=>r.combat.snapshot.activeMove.lastHit=false,r=>r.combat.snapshot.activePokemon='[Pokemon:p1a]',r=>r.combat.snapshot.activeTarget='[Pokemon:p1b]',r=>r.combat.snapshot.activeMove.hitTargets=[...(r.combat.snapshot.activeMove.hitTargets||[]),'[Pokemon:p1b]'],r=>r.combat.snapshot.activeMove.moveHitData={...(r.combat.snapshot.activeMove.moveHitData||{}),p1b:{}},r=>r.combat.snapshot.midTurn=true,r=>r.pendingMysteryEntryBoost='uncommon-breed']){const run=wildEventReviewFixture('uncommon-breed').classic.slots[0];mutate(run);const before=structuredClone(run);assert.equal(classicMoveAliasPreview(run,'one'),null);assert.deepEqual(run,before);}});
test('reviewed wild event group preserves verified challenge eligibility and capture',async()=>{const {classicChallengeBattleEligibility}=await import('../lib/rogue-challenge-eligibility.mjs');for(const type of ['mysterious-chest','berries','fight-or-flight','uncommon-breed'])for(const sketch of [false,true]){let doc=wildEventReviewFixture(type,{sketch,challenge:true}),run=doc.classic.slots[0];assert.equal(run.screen,'battle',type);const before=structuredClone(run),view=classicGameView(doc),mon=run.party.find(p=>p.boxId==='one'),eligible=classicChallengeBattleEligibility(mon,run.challenges),preview=view.run.party.find(p=>p.boxId==='one').moveAliasRepair;assert.ok(preview,JSON.stringify({type,sketch}));applyClassicAction(doc,{action:'repairMoveAliases',boxId:'one',confirm:true,expectedMoves:preview.moves,...(sketch?{removeIndex:2,expectedSketchPP:preview.sketchPP}:{})});assert.equal(classicChallengeBattleEligibility(run.party.find(p=>p.boxId==='one'),run.challenges),eligible);assert.deepEqual(run.challenges,before.challenges);assert.deepEqual(run.combat.challengeRestrictions,before.combat.challengeRestrictions);assert.deepEqual(classicGameView(doc).battle.requests,view.battle.requests);doc=await decodeGameData(await encodeGameData(doc));run=doc.classic.slots[0];applyClassicAction(doc,{action:'capture',ballId:'masterball'});run=doc.classic.slots[0];assert.ok(run.mysteryState.completedWaves.includes(22),type);assert.deepEqual(run.challenges,before.challenges);assert.deepEqual(doc.classic.slots[1],{id:'other',safe:true});}});
